<?php
namespace Modules\BankingCoreDeposits\Http\Controllers;
use Illuminate\Http\Request; use Illuminate\Routing\Controller; use Modules\BankingCoreDeposits\Entities\StandingInstruction;
class StandingInstructionController extends Controller { public function index(){ $items=StandingInstruction::latest()->paginate(25); return view('bankingcoredeposits::standing-instructions.index',compact('items')); } public function create(){ return view('bankingcoredeposits::standing-instructions.create'); } public function store(Request $request){ StandingInstruction::create($request->all()); return redirect()->route('banking.core-deposits.standing-instructions.index'); } public function show(StandingInstruction $standingInstruction){ return view('bankingcoredeposits::standing-instructions.show',compact('standingInstruction')); } public function edit(StandingInstruction $standingInstruction){ return view('bankingcoredeposits::standing-instructions.edit',compact('standingInstruction')); } public function update(Request $request, StandingInstruction $standingInstruction){ $standingInstruction->update($request->all()); return back(); } public function destroy(StandingInstruction $standingInstruction){ $standingInstruction->delete(); return back(); } }
